function countDistinct(s) {
  const n = s.length;
  const BASE = 131;
  const MOD1 = 1000000007;
  const MOD2 = 998244353;
  const seen = new Set();

  for (let start = 0; start < n; start++) {
    let hash1 = 0;
    let hash2 = 0;
    for (let end = start; end < n; end++) {
      const code = s.charCodeAt(end);
      hash1 = (hash1 * BASE + code) % MOD1;
      hash2 = (hash2 * BASE + code) % MOD2;
      seen.add(hash1 + ',' + hash2 + ',' + (end - start + 1));
    }
  }
  return seen.size;
}

