function generate(rand, size) {
  const n = size === 'large' ? 300 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 10);
  const letters = [1, 2, 3, 26][Math.floor(rand() * 4)];
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  return [s];
}
